create or replace function public.report_balances_owed() returns jsonb language plpgsql stable security definer set search_path to 'public' as $fn$ declare v jsonb; begin if not public.is_admin() then raise exception 'reports are office-only' using errcode = '42501'; end if; with live as (select * from public.jobs where coalesce(ghl_status, '') not in ('lost', 'abandoned')), td as (select job_id, sum(amount) paid, max(payment_date) last_paid, count(*) n from public.client_payments group by job_id), sh as (select job_id, sum(coalesce(amount_collected, 0)) paid, max(date_collected) last_paid, sum(coalesce(contract_amount, 0)) contract, bool_or(section = 'awaiting_payment') awaiting, count(*) n from public.completion_log_rows where match_status in ('matched', 'manual') and job_id is not null group by job_id), comp as (select * from public.job_completion_dates()), r as (select l.id job_id, l.number, l.ghl_project_display_id project_ref, l.customer_name customer, l.customer_address address, l.trade, l.stage, coalesce(s.label, l.stage) stage_label, coalesce(s.is_complete, false) finished, coalesce(l.contract_amount, 0) contract, coalesce(td.paid, 0) paid_tradedesk, coalesce(td.n, 0) tradedesk_payments, td.last_paid last_paid_tradedesk, sh.paid paid_sheet, sh.last_paid last_paid_sheet, sh.contract contract_sheet, coalesce(sh.awaiting, false) sheet_awaiting, sh.n is not null in_sheet, c.completed_at from live l left join public.job_stages s on s.key = l.stage left join td on td.job_id = l.id left join sh on sh.job_id = l.id left join comp c on c.job_id = l.id), x as (select r.*, greatest(paid_tradedesk, coalesce(paid_sheet, 0)) collected, case when coalesce(paid_sheet, 0) > paid_tradedesk + 0.5 then 'sheet' when paid_tradedesk > 0 then 'tradedesk' else 'none' end collected_source from r) select jsonb_build_object('generated_at', now(), 'rows', coalesce((select jsonb_agg(to_jsonb(x) || jsonb_build_object('balance', x.contract - x.collected, 'days_since_complete', case when x.completed_at is not null then (now() at time zone 'America/New_York')::date - (x.completed_at at time zone 'America/New_York')::date end) order by (x.contract - x.collected) desc) from x), '[]'::jsonb)) into v; return v; end $fn$;
comment on function public.report_balances_owed() is 'Balance owed per live job (not lost/abandoned). balance = contract - collected; collected = greater of TradeDesk client_payments and the Completion Log sheet amount_collected (matched/manual rows, summed). collected_source says which won. finished = job_stages.is_complete. Admin only.';
revoke execute on function public.report_balances_owed() from public, anon;
grant execute on function public.report_balances_owed() to authenticated;;
